    checks.append(g.compare(bridge._size(g,mouth_row),g.math('ADD',n,1.)))
    metrics.update(mouth_count=bridge._size(g,mouth_row),mouth_expected=g.math('ADD',n,1.))
    sign=g.switch(is_end,1.,-1.)
    tangent=g.vector('SCALE',mouth('tangent','FLOAT_VECTOR'),sign)
    across=g.right(tangent);authored_lateral=g.vector('SCALE',lateral,sign)
    origin=g.vector('SUBTRACT',center,g.vector('SCALE',authored_lateral,g.math('MULTIPLY',.5,width)))
