    mouth_point=g.vector('ADD',origin,g.vector('SCALE',authored_lateral,g.math('MULTIPLY',width,u)))
    row_start=g.sample(row,pos,0,'FLOAT_VECTOR');row_end=g.sample(row,pos,row_n,'FLOAT_VECTOR')
    row_point=bridge._mix(g,row_start,row_end,u)
    fraction=g.math('DIVIDE',g.vector('DOT_PRODUCT',g.vector('SUBTRACT',pos,mouth_point),tangent),
        g.vector('DOT_PRODUCT',g.vector('SUBTRACT',row_point,mouth_point),tangent))
    local_s=g.math('MULTIPLY',first_distance,fraction)
    replacement=g.store(replacement,'st_path_s',g.switch(is_end,local_s,g.math('SUBTRACT',1.,local_s)))
    replacement=g.store(replacement,'st_path_u',u)
    inner=g.close(u,meta('inner_u'),1e-6)
    for name,value in (('st_path_inner_boundary',inner),('plateau_boundary',inner),
        ('st_path_half_profile',True),('st_mouth_vertex',g.close(fraction,0.,1e-7))):
        replacement=g.store(replacement,name,value,'BOOLEAN')
    for name,value in (('st_path_id',sid),('st_bundle_id',meta('bundle_id','INT')),('st_component_kind',0),
                       ('st_transition_id',-1)):
        replacement=g.store(replacement,name,value,'INT','FACE')
    replacement=g.store(replacement,'st_paired_profile_transition',True,'BOOLEAN','FACE')
    row_side=g.switch(is_end,1,0,'INT')
    from_row=g.compare(g.named('_bridge_source_side'),row_side,kind='INT')
    original_index=g.sample(row,g.named('_terminal_vertex'),g.named('_bridge_source_index'),'INT')
