    metrics.update(weld_agreement=agreement,
        weld_reduction=g.math('SUBTRACT',bridge._size(g,combined),bridge._size(g,merged)))
    merged=g.store(merged,'_paired_transition_code',call.outputs['Diagnostic Code'],'INT')
    g.set(merged,ro.inputs['Mesh']);g.set(g.all(ri.outputs['Valid'],*checks),ro.inputs['Valid'])
    if diagnostics:
        line=g.node('GeometryNodeMeshLine','One diagnostic per paired member terminal');line.inputs['Count'].default_value=1
        record=line.outputs['Mesh']
